  const { totalMinor } = priceOrder({ lines: [line(unit)], coupons: [{ type: 'percent', value: 50 }] });
  // discount = roundHalfEven(unit * 50, 100) = 4503599627370495.5 -> 4503599627370496 (even)
  assert.equal(totalMinor, unit - 4503599627370496);
